"""Concatenate file contents."""

_open_registry = []


def read_all(paths):
    parts = []
    for p in paths:
        f = open(p)
        _open_registry.append(f)
        try:
            parts.append(f.read())
        finally:
            _open_registry.remove(f)
            f.close()
    return "".join(parts)


def open_handle_count():
    return len(_open_registry)

