def test_handles_closed_when_read_fails(self):
    class ReadFails:
        def __init__(self):
            self.closed = False

        def read(self):
            raise OSError("simulated read error")

        def close(self):
            self.closed = True

    real_open = builtins.open
    builtins.open = lambda *args, **kwargs: ReadFails()
    self.addCleanup(setattr, builtins, "open", real_open)
    with self.assertRaises(OSError):
        readall.read_all([self.a])
    self.assertEqual(readall.open_handle_count(), 0,
                     "registry must not retain a handle whose read failed")

